with a as(select * from public.authors where open_library_id=any(array['OL2675573A']::text[])),w as(select * from public.works where open_library_id=any(array['OL1892618W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789035141704','9780553804362']::text[]) or open_library_edition_id=any(array['OL40284495M','OL7850566M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987107001 and 987107999),'editions',(select count(*) from public.editions where id between 987207001 and 987207999),'authors',(select count(*) from public.authors where id between 987307001 and 987307999))) as preflight;
